"""Original reference designs for human review, never claimed as model outputs."""

MOTION_HOOK = '''function useMotion(){
 const ref=React.useRef<HTMLElement>(null);
 React.useEffect(()=>{
  const root=ref.current;if(!root)return;
  const media=matchMedia('(prefers-reduced-motion: reduce)');let frame=0;
  const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){(entry.target as HTMLElement).dataset.seen='true';observer.unobserve(entry.target);}}),{threshold:.12});
  const watched=new WeakSet<Element>();const register=()=>root.querySelectorAll('[data-reveal]').forEach(el=>{if(!watched.has(el)){watched.add(el);observer.observe(el);}});
  register();const mutations=new MutationObserver(register);mutations.observe(root,{childList:true,subtree:true});root.classList.add('motion-ready');
  const update=()=>{frame=0;root.style.setProperty('--shift',media.matches?'0px':`${Math.min(scrollY*.13,85)}px`);};
  const scroll=()=>{if(!frame)frame=requestAnimationFrame(update);};
  window.addEventListener('scroll',scroll,{passive:true});media.addEventListener('change',scroll);update();
  return ()=>{observer.disconnect();mutations.disconnect();cancelAnimationFrame(frame);window.removeEventListener('scroll',scroll);media.removeEventListener('change',scroll);root.classList.remove('motion-ready');};
 },[]);return ref;
}
'''

COMMON_CSS = '''*{box-sizing:border-box}body{margin:0}html{scroll-behavior:smooth}button,input,select,textarea{font:inherit}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:inherit;text-underline-offset:5px}button:disabled{cursor:default;opacity:.5}svg{max-width:100%;height:auto}h1,h2,h3,p{margin-top:0}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #bb510d;outline-offset:5px}.motion-ready [data-reveal]{opacity:0;transform:translateY(20px);transition:opacity .65s ease,transform .65s ease}.motion-ready [data-reveal][data-seen=true]{opacity:1;transform:none}small{font-size:12px;line-height:1.6}footer{padding:24px 6vw;border-top:1px solid currentColor;font-size:12px}nav{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 6vw;font-size:13px}nav strong{letter-spacing:.08em}nav div{display:flex;gap:22px}section{scroll-margin-top:20px}[data-art]{transform:translateY(var(--shift,0px))}button{border:1px solid currentColor;padding:12px 18px;background:transparent;color:inherit}button[aria-pressed=true]{background:var(--ink);color:var(--paper)}[role=status]{min-height:1.5em}@media(max-width:700px){nav{align-items:start}nav div{gap:12px;flex-wrap:wrap}footer{padding:22px 6vw}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.motion-ready [data-reveal]{opacity:1;transform:none;transition:none}[data-art]{transform:none!important}*,*::before,*::after{animation:none!important}}
'''

